import{_ as s,C as l,o as i,c as r,a3 as n,b as m,w as t,a as o,E as u,a4 as k}from"./chunks/framework.BvvarXmc.js";const h="/screenshots/kantin-daily-limits.png",_=JSON.parse('{"title":"Batas Belanja Harian Siswa (Daily Limits)","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-kantin/limit-harian.md","filePath":"panduan-kantin/limit-harian.md","lastUpdated":null}'),d={name:"panduan-kantin/limit-harian.md"};function g(b,a,p,c,j,S){const e=l("Mermaid");return i(),r("div",null,[a[1]||(a[1]=n('<h1 id="batas-belanja-harian-siswa-daily-limits" tabindex="-1">Batas Belanja Harian Siswa (Daily Limits) <a class="header-anchor" href="#batas-belanja-harian-siswa-daily-limits" aria-label="Permalink to &quot;Batas Belanja Harian Siswa (Daily Limits)&quot;">​</a></h1><p>Fitur <strong>Batas Belanja Harian</strong> adalah sistem proteksi keuangan cerdas yang memungkinkan sekolah dan orang tua murid mengatur batas maksimal nominal uang jajan yang dapat dibelanjakan oleh seorang siswa di kantin sekolah dalam satu hari.</p><p>Fitur ini dapat diakses oleh Administrator dan Pengelola Kantin melalui menu <strong>Kantin</strong> &gt; <strong>Kelola Limit Harian</strong> pada sidebar aplikasi.</p><hr><h2 id="tampilan-halaman-kelola-limit-harian" tabindex="-1">Tampilan Halaman Kelola Limit Harian <a class="header-anchor" href="#tampilan-halaman-kelola-limit-harian" aria-label="Permalink to &quot;Tampilan Halaman Kelola Limit Harian&quot;">​</a></h2><p>Berikut adalah tampilan antarmuka manajemen limit belanja harian:</p><p><img src="'+h+'" alt="Kelola Limit Harian Kantin"></p><hr><h2 id="tujuan-manfaat-fitur-batas-jajan" tabindex="-1">Tujuan &amp; Manfaat Fitur Batas Jajan <a class="header-anchor" href="#tujuan-manfaat-fitur-batas-jajan" aria-label="Permalink to &quot;Tujuan &amp; Manfaat Fitur Batas Jajan&quot;">​</a></h2><ol><li><strong>Mencegah Pemborosan Uang Saku</strong>: Siswa belajar mengelola uang sakunya dengan bijak agar tidak menghabiskan seluruh saldo dompet digital dalam sekali istirahat.</li><li><strong>Proteksi Kartu Pelajar yang Hilang</strong>: Jika kartu pintar siswa jatuh atau hilang, penemu kartu tidak dapat menguras seluruh saldo karena transaksi otomatis dibatasi oleh limit harian.</li><li><strong>Mendukung Pola Makan Sehat Siswa</strong>: Orang tua murid dapat membatasi konsumsi makanan ringan di luar bekal rumah yang dibawa anak.</li><li><strong>Ketenangan bagi Orang Tua</strong>: Orang tua dapat menitipkan saldo dalam jumlah besar (misal: Rp 200.000 untuk kebutuhan satu bulan) tanpa khawatir uang tersebut habis dalam 1–2 hari.</li></ol><hr><h2 id="_2-tingkatan-limit-belanja" tabindex="-1">2 Tingkatan Limit Belanja <a class="header-anchor" href="#_2-tingkatan-limit-belanja" aria-label="Permalink to &quot;2 Tingkatan Limit Belanja&quot;">​</a></h2><p>Sistem menerapkan hierarki proteksi dua tingkat yang sangat fleksibel:</p>',13)),(i(),m(k,null,{default:t(()=>[u(e,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22Siswa%20Melakukan%20Pembayaran%20di%20Kasir%20POS%22%5D%20--%3E%20B%7B%22Ada%20Limit%20Khusus%20Siswa%3F%22%7D%0A%20%20%20%20B%20--%3E%7CAda%20Limit%20Khusus%7C%20C%5B%22Terapkan%20Limit%20Khusus%20Siswa%22%5D%0A%20%20%20%20B%20--%3E%7CGunakan%20Standar%7C%20D%5B%22Terapkan%20Batas%20Umum%20Sekolah%22%5D%0A%20%20%20%20C%20--%3E%20E%7B%22Sisa%20Kuota%20Belanja%20Masih%20Cukup%3F%22%7D%0A%20%20%20%20D%20--%3E%20E%0A%20%20%20%20E%20--%3E%7CMasih%20Cukup%7C%20F%5B%22Transaksi%20Disetujui%20%26%20Saldo%20Terpotong%22%5D%0A%20%20%20%20E%20--%3E%7CMelebihi%20Kuota%7C%20G%5B%22Transaksi%20Ditolak%3A%20Melebihi%20Kuota%20Harian%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h3 id="_1-batas-umum-sekolah-general-limit" tabindex="-1">1. Batas Umum Sekolah (<em>General Limit</em>) <a class="header-anchor" href="#_1-batas-umum-sekolah-general-limit" aria-label="Permalink to &quot;1. Batas Umum Sekolah (*General Limit*)&quot;">​</a></h3><p>Batas global yang berlaku untuk seluruh siswa di sekolah secara otomatis. Misalnya sekolah menetapkan standar umum maksimal jajan sebesar <strong>Rp 25.000 per hari</strong>.</p><h3 id="_2-batas-khusus-per-siswa-custom-student-limit" tabindex="-1">2. Batas Khusus per Siswa (<em>Custom Student Limit</em>) <a class="header-anchor" href="#_2-batas-khusus-per-siswa-custom-student-limit" aria-label="Permalink to &quot;2. Batas Khusus per Siswa (*Custom Student Limit*)&quot;">​</a></h3><p>Batas nominal khusus yang ditetapkan atas permintaan wali murid untuk anak tertentu. Limit khusus ini akan mengabaikan (<em>override</em>) batas umum sekolah. Misalnya orang tua meminta anaknya hanya boleh jajan maksimal <strong>Rp 10.000 per hari</strong>.</p><hr><h2 id="alur-menetapkan-batas-belanja-khusus-siswa" tabindex="-1">Alur Menetapkan Batas Belanja Khusus Siswa <a class="header-anchor" href="#alur-menetapkan-batas-belanja-khusus-siswa" aria-label="Permalink to &quot;Alur Menetapkan Batas Belanja Khusus Siswa&quot;">​</a></h2><ol><li>Pada halaman <strong>Kelola Limit Harian</strong>, klik tombol ungu <strong><code>+ Tambah Limit</code></strong> di pojok kanan atas tabel.</li><li>Jendela modal formulir akan terbuka. Isi kolom-kolom berikut: <ul><li><strong>Pilih Siswa</strong> <em>(Wajib)</em>: Cari nama siswa atau NISN yang ingin diatur batas belanjanya.</li><li><strong>Nominal Limit Harian (Rp)</strong> <em>(Wajib)</em>: Masukkan angka batas maksimal belanja dalam sehari (contoh: <code>15000</code>).</li><li><strong>Keterangan / Alasan</strong>: Catatan alasan penetapan limit (contoh: <em>Permintaan ibu kandung via buku penghubung</em> atau <em>Anak dalam program diet makanan manis</em>).</li><li><strong>Status Limit</strong>: Pilih status <strong>Aktif</strong>.</li></ul></li><li>Klik tombol <strong>Simpan Limit</strong>.</li><li>Pembatasan ini seketika berlaku aktif secara realtime pada seluruh loket kasir POS kantin.</li></ol><hr><h2 id="reaksi-sistem-di-kasir-pos-saat-siswa-melebihi-batas" tabindex="-1">Reaksi Sistem di Kasir POS Saat Siswa Melebihi Batas <a class="header-anchor" href="#reaksi-sistem-di-kasir-pos-saat-siswa-melebihi-batas" aria-label="Permalink to &quot;Reaksi Sistem di Kasir POS Saat Siswa Melebihi Batas&quot;">​</a></h2><p>Ketika siswa yang telah mencapai limit harian mencoba berbelanja lagi di kasir kantin:</p><ol><li>Layar kasir POS seketika memunculkan peringatan berwarna merah: <blockquote><p><strong>Peringatan: Melebihi Batas Belanja Harian!</strong><br> Siswa ini telah berbelanja sebesar Rp 15.000 dari batas maksimal Rp 15.000 per hari.</p></blockquote></li><li>Tombol pemotongan saldo dompet digital kartu terkunci otomatis demi melindungi saldo siswa.</li><li>Kasir dapat menyarankan siswa untuk menunggu hari esok saat kuota harian kembali ter-reset otomatis di jam 00.00 malam, atau membayar menggunakan uang tunai jika diizinkan oleh kebijakan sekolah.</li></ol>',11))])}const w=s(d,[["render",g]]);export{_ as __pageData,w as default};
